import{S as n,o as t,c as h,a9 as p,B as l}from"./chunks/framework.DxG24V0C.js";const k="/agentsrc/images/codex/02-reactor-engine.svg",e="/agentsrc/images/codex/02-steering-mechanism.svg",r="/agentsrc/images/codex/02-run-turn-loop.svg",c=JSON.parse('{"title":"Codex 主循环：一条消息是如何在 Reactor 中流转的？","description":"","frontmatter":{"title":"Codex 主循环：一条消息是如何在 Reactor 中流转的？"},"headers":[],"relativePath":"codex/02-mainloop.md","filePath":"codex/02-mainloop.md","lastUpdated":1788847143000}'),d={name:"codex/02-mainloop.md"},y=Object.assign(d,{setup(E){const i=[{question:"在 Codex 的架构中，submission_loop 函数在没有事件输入时，处于什么状态？",options:["阻塞在对 LLM 推理 API 的网络请求回调上，等待模型返回生成的文本","阻塞在 async_channel 的 recv() 方法上，等待接收新的 Submission 消息","处于高频的 while-true 自旋轮询状态，不断检查各个工具的执行进度","阻塞在终端标准输入的 read_line 方法上，等待用户敲击键盘输入字符"],correct:1,explanation:"submission_loop 是一个单消费者接收端，它通过 rx_sub.recv().await 阻塞等待。这种设计使得它能在等待期间随时被其他来源（如系统定时器、IDE 请求）的消息唤醒。"},{question:"当 Codex 正在执行一个耗时的代码生成任务时，用户突然输入了新指令，系统默认会如何处理？",options:["将新指令加入待处理队列，等当前代码生成任务完全结束后再按顺序启动新任务","直接在当前线程中同步执行新指令，阻塞后续的所有模型请求和本地工具调用","通过 steer_input 尝试介入当前活跃任务，将新输入追加到当前 Turn 的待处理队列","调用当前 SessionTask 的 abort 方法强制终止旧任务，然后立刻清空历史并重启"],correct:2,explanation:"Codex 引入了 Steering（介入）机制。如果当前有活跃的 RegularTask，新输入会被追加到当前 turn 的 pending input 中，模型在下一次工具循环间隙会感知到这个新指令，而不是直接强杀。"},{question:"在 Codex 的任务取消机制中，系统是如何安全地掐断正在进行的网络请求或工具进程的？",options:["通过操作系统的 kill -9 信号直接杀死后台运行的 Tokio 工作线程以释放内存","采用协作式取消（CancellationToken）、优雅等待超时，最后兜底强杀与清理","修改数据库中的 Session 状态位，让底层的工具进程自行轮询并决定是否退出","断开与 App Server 的 WebSocket 连接，强制引发底层的网络读写异常来中断"],correct:1,explanation:"Codex 的取消是三段式的：先触发 CancellationToken 广播取消信号，等待一段 graceful timeout 期望任务自行清理，如果超时仍未退出，再调用 task.handle.abort() 强杀并执行 abort hook。"},{question:"对比 Claude Code，Codex 选择 Reactor 模式而非 async generator 的核心工程考量是什么？",options:["async generator 在处理海量上下文时会导致严重的内存泄漏和系统性能衰退","Reactor 模式能显著降低 LLM 推理的延迟，提升首字响应速度与用户体验","适配多端并发输入需求，并更贴合 Rust/Tokio 生态中基于消息传递的工程惯性","async generator 无法支持动态工具注册和 MCP 协议的双向集成与权限拦截"],correct:2,explanation:"Reactor 模式天然适合 App Server 处理 IDE 并发请求的多生产者场景。同时，通过 Channel 传递消息转移所有权，比在 Rust 中跨 yield 维护复杂借用关系更符合工程惯性。"},{question:"在 run_turn 的真实流转中，上下文压缩（Compaction）发生在什么时机？",options:["仅在用户手动发送 Op::Compact 消息时，才会暂停当前任务执行上下文压缩","仅在模型返回 tool_calls 之前，系统会统一对历史工具结果进行一次压缩","在采样循环开始前有一道防线，在每次模型返回后（自动压缩）还有一道防线","仅在整个 run_turn 彻底结束后，系统会在后台起一个独立线程进行异步压缩"],correct:2,explanation:"run_turn 流程中，首先会执行 run_pre_sampling_compact，然后在采样循环内部，每次模型返回后还会执行 run_auto_compact，微观循环被严密地包裹在 Token 预算监控之下。"}];return(o,s)=>{const a=n("Quiz");return t(),h("div",null,[s[0]||(s[0]=p("",51)),l(a,{questions:i})])}}});export{c as __pageData,y as default};
